## Why This Is Asked
Tests practical RN data fetching, list rendering, and basic UX states (loading, empty) in a beginner-friendly scenario.

## Key Concepts
- FlatList usage: data, renderItem, keyExtractor, onRefresh, refreshing
- Loading skeleton vs content
- Empty state handling and accessibility
- Rendering performance: memoized renderItem, stable keys

## Code Example
```javascript
import React, {useEffect, useMemo, useState} from 'react';
import {FlatList, View, Text, ActivityIndicator, StyleSheet} from 'react-native';

const mockApi = () => new Promise(res => setTimeout(() => res([
  {id: '1', title: 'Item One'},
  {id: '2', title: 'Item Two'},
  {id: '3', title: 'Item Three'}
]), 1000));

export default function ItemFeed() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    const res = await mockApi();
    setData(res);
    setLoading(false);
  };

  useEffect(() => { fetchData(); }, []);

  const renderItem = useMemo(() => ({ item }) => (
    <View style={styles.card}>
      <Text style={styles.title}>{item.title}</Text>
    </View>
  ), []);

  const onRefresh = async () => {
    setRefreshing(true);
    await fetchData();
    setRefreshing(false);
  };

  if (loading) {
    return (
      <View style={styles.skeleton}>
        <ActivityIndicator size="small" />
        <Text>Loading…</Text>
      </View>
    );
  }

  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id}
      renderItem={renderItem}
      onRefresh={onRefresh}
      refreshing={refreshing}
      ListEmptyComponent={<Text style={styles.empty}>No items available</Text>}
    />
  );
}

const styles = StyleSheet.create({
  card: { padding: 12, borderBottomWidth: 1, borderColor: '#eee' },
  title: { fontSize: 16 },
  skeleton: { padding: 20, alignItems: 'center' },
  empty: { padding: 20, textAlign: 'center', color: '#666' }
});
```

